// === embed.js com loader confiável ===
(function () {
    console.log("[chatagentes] embed.js carregado");

    // 1) injeta keyframes do spinner
    // injeta keyframes completos e registra no documento
    const keyframes = `
    @keyframes chatagentes-spin {
      0%   { transform: rotate(0deg); }
      100% { transform: rotate(360deg); }
    }
  `;
    const style = document.createElement("style");
    style.innerHTML = keyframes;
    document.head.appendChild(style);

    const BASE = "https://chatagentes.com";
    const CONTAINER_ID = "chatagentes-container";
    const CONTAINER_IFRAME_ID = "chatagentes-container-iframe";
    const BUBBLE_ID = "chatagentes-bubble";
    const SPINNER_ID = "chatagentes-spinner";
    const IFRAME_ID = "chatagentes-iframe";
    let lastOpts = {};
    let chatOpen = false;
    let iframeLoaded = false;

    // Adiciona listener para mensagens do iframe
    window.addEventListener('message', function (event) {
        if (event.data?.type === 'chatagentes-close') {
            closeChat();
        }
    });

    // 2) processa a fila antes de carregar
    const rawQueue = Array.isArray(window.chatagentes?.q) ? window.chatagentes.q : [];
    rawQueue.forEach(args => {
        const [cmd, opts] = Array.from(args);
        if (cmd === "open") lastOpts = opts;
    });

    // 3) substitui stub
    window.chatagentes = (cmd, opts) => {
        if (cmd === "open") {
            lastOpts = opts;
            openChat(opts);
        }
        if (cmd === "close") {
            closeChat();
        }
    };
    window.chatagentes.getState = "initialized";

    function createContainer({ slug, width } = {}) {
        if (!slug) return console.error("[chatagentes] precisa de { slug }");
        const isMobile = window.innerWidth < 768;

        // monta container fixo e responsivo verticalmente
        const c = document.createElement("div");
        c.id = CONTAINER_ID;
        Object.assign(c.style, {
            position: "fixed",
            top: isMobile ? "0" : "20px",
            bottom: isMobile ? "0" : "85px",
            right: isMobile ? "0" : "20px",
            left: isMobile ? "0" : "auto",
            width: isMobile ? "100%" : (width || "90vw"),
            height: isMobile ? "100%" : "auto",
            maxWidth: isMobile ? "100%" : "450px",
            border: "1px solid #e5e7eb",
            boxShadow: "0 0 10px 0 rgba(0, 0, 0, 0.1)",
            background: "#fff",
            zIndex: 9999,
            overflow: "hidden",
            borderRadius: isMobile ? "0" : "8px",
            display: "none" // Inicialmente oculto
        });
        const spinner = document.createElement("div");
        spinner.id = SPINNER_ID;
        Object.assign(spinner.style, {
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: "40px",
            height: "40px",
            border: "4px solid rgba(0,0,0,0.1)",
            borderTop: "4px solid #000",
            borderRadius: "50%",
            zIndex: 10000,
            animationName: "chatagentes-spin",
            animationDuration: "1s",
            animationIterationCount: "infinite",
            animationTimingFunction: "linear"
        });
        c.appendChild(spinner);

        return document.body.appendChild(c);
    }

    function createIframeContainer({ slug, url, width } = {}) {
        if (!slug) return console.error("[chatagentes] precisa de { slug }");
        const isMobile = window.innerWidth < 768;

        const containerIframe = document.createElement("div");
        containerIframe.id = CONTAINER_IFRAME_ID;
        Object.assign(containerIframe.style, {
            position: "fixed",
            top: isMobile ? "0" : "20px",
            bottom: isMobile ? "0" : "85px",
            right: isMobile ? "0" : "20px",
            left: isMobile ? "0" : "auto",
            width: isMobile ? "100%" : (width || "90vw"),
            height: isMobile ? "100%" : "auto",
            maxWidth: isMobile ? "100%" : "450px",
            zIndex: 9999,
            overflow: "hidden",
            borderRadius: isMobile ? "0" : "8px",
            display: "none" // Inicialmente oculto
        });
        document.body.appendChild(containerIframe);

        // cria iframe
        const iframe = document.createElement("iframe");
        iframe.id = IFRAME_ID;
        iframe.style.visibility = "hidden";
        iframe.style.width = "100%";
        iframe.style.height = "100%";
        iframe.style.border = "0";
        iframe.src = url || `${BASE}/chat/${slug}`;

        iframe.addEventListener("load", () => {
            const container = document.getElementById(CONTAINER_ID);
            container.style.display = "none";
            iframe.style.visibility = "visible";
            iframeLoaded = true;
            containerIframe.style.display = "block";
            console.log("[chatagentes] iframe carregado");
        });

        containerIframe.appendChild(iframe);
        return containerIframe;
    }

    function openChat(opts = lastOpts) {
        if (!opts || !opts.slug) {
            console.error("[chatagentes] precisa de { slug }");
            return;
        }

        let containerIframe = document.getElementById(CONTAINER_IFRAME_ID);
        if (!containerIframe) {
            containerIframe = createIframeContainer(opts);
        }

        let container = document.getElementById(CONTAINER_ID);
        if (!container) {
            container = createContainer(opts);
        }

        if (iframeLoaded) {
            containerIframe.style.display = "block";
        } else {
            container.style.display = "block";
        }

        chatOpen = true;
        createBubble();
        console.log("[chatagentes] chat aberto");
    }

    function closeChat() {
        const containerIframe = document.getElementById(CONTAINER_IFRAME_ID);
        if (containerIframe) {
            containerIframe.style.display = "none";
        }

        const container = document.getElementById(CONTAINER_ID);
        if (container) {
            container.style.display = "none";
        }

        chatOpen = false;
        createBubble();
        console.log("[chatagentes] chat fechado");
    }

    // 6) cria o botão-bolha abaixo do container
    function createBubble() {
        document.getElementById(BUBBLE_ID)?.remove();
        const isMobile = window.innerWidth < 768;

        // Em dispositivos móveis, o balão não deve ser exibido quando o chat estiver aberto
        if (isMobile && chatOpen) {
            return;
        }

        const b = document.createElement("div");
        b.id = BUBBLE_ID;
        Object.assign(b.style, {
            position: "fixed",
            right: "20px",
            bottom: "20px",
            width: "55px",
            height: "55px",
            borderRadius: "50%",
            background: "#000",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            cursor: "pointer",
            transition: "transform 0.2s, background 0.2s",
            zIndex: 10000
        });

        b.innerHTML = chatOpen
            ? `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#ffffff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>`
            : `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#ffffff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path></svg>`;

        b.addEventListener("mouseenter", () => {
            b.style.transform = "scale(1.1)";
            b.style.background = "#333";
        });
        b.addEventListener("mouseleave", () => {
            b.style.transform = "scale(1)";
            b.style.background = "#000";
        });
        b.addEventListener("click", () => {
            if (chatOpen) {
                closeChat();
            } else {
                openChat(lastOpts);
            }
        });

        document.body.appendChild(b);
        console.log("[chatagentes] bubble criado, chatOpen=", chatOpen);
    }

    // 7) cria a bolha inicial
    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", createBubble);
    } else {
        createBubble();
    }
})();
